        lanceInicial: leilao.lanceInicial,
        incrementoMinimo: leilao.incrementoMinimo,
        prorrogacaoSegundos: leilao.prorrogacaoSegundos,
        encerraEm: leilao.encerraEm,
      });
      r.agendar$.next(encerraEmMs);
      return { ...leilao };
    });
  }

