        titulo: l.titulo,
        valor: l.maiorLance.valor,
        ocorridoEm: data.toISOString(),
      });
    }
    r.agendar$.complete();
    r.ao$.complete();
  }

  private emitir(
    r: Registro,
    tipo: TipoEvento,
    data: Date,
    dados: Record<string, unknown>,
  ): void {
    const evento: Evento = {
      sequencia: r.eventos.length + 1,
      tipo,
      leilaoId: r.leilao.id,
      ocorridoEm: data.toISOString(),
      dados,
    };
    r.eventos.push(evento);
    r.ao$.next(evento);
  }

