      l.maiorLance = { participante, valor, ocorridoEm: data.toISOString() };
      l.totalLances++;
      this.emitir(r, 'LanceAceito', data, { participante, valor });
      if (anterior) {
        this.notificar(anterior.participante, {
          tipo: 'LANCE_SUPERADO',
          leilaoId: l.id,
          titulo: l.titulo,
          valorAnterior: anterior.valor,
          novoValor: valor,
          ocorridoEm: data.toISOString(),
