  private tentarEncerrar(r: Registro): void {
    const l = r.leilao;
    if (l.status === 'ENCERRADO') return;
    const agora = Date.now();
    if (agora < r.encerraEmMs) {
      r.agendar$.next(r.encerraEmMs); // timer disparou cedo demais
